package com.vasiliyrogozhin85.upospa;
import org.json.*;import java.util.*;
final class OemProfileEngine{
 static JSONObject profile(JSONObject report){JSONObject out=new JSONObject();try{JSONObject d=report.optJSONObject("device");String m=d==null?"":d.optString("manufacturer").toLowerCase(Locale.US);String family="generic";String notes="Стандартный Android ADB/Fastboot профиль.";if(m.contains("samsung")){family="samsung";notes="Samsung: Fastboot часто недоступен; для официальной прошивки обычно используется Download Mode/Odin-протокол.";}else if(m.contains("xiaomi")||m.contains("redmi")||m.contains("poco")){family="xiaomi";notes="Xiaomi/Redmi/POCO: проверяйте unlock state, anti-rollback и соответствие codename.";}else if(m.contains("google")){family="pixel";notes="Pixel: стандартный Fastboot/Fastbootd, A/B и OTA payload обычно хорошо поддерживаются.";}else if(m.contains("oneplus")||m.contains("oppo")||m.contains("realme")){family="oplus";notes="OnePlus/OPPO/Realme: проверяйте Fastbootd, dynamic partitions и OEM-специфичные ограничения.";}else if(m.contains("motorola")){family="motorola";notes="Motorola: стандартный Fastboot с OEM-переменными; важна точная модель/SKU.";}else if(m.contains("doogee")){family="doogee";notes="DOOGEE: часто MediaTek; дополнительно проверяйте scatter/partition layout и preloader риски.";}out.put("family",family);out.put("notes",notes);}catch(Exception ignored){}return out;}
 private OemProfileEngine(){}
}
